import re

def extract_code(reply: str) -> str:
    fence = re.search(
        r"```[ \t]*(?:python|py)(?:3)?[ \t]*\r?\n(.*?)```",
        reply,
        re.DOTALL | re.IGNORECASE,
    )
    if fence:
        return fence.group(1).strip("\r\n")

    for line in re.finditer(
        r"(?m)^[ \t]*(?:def|from|import)(?=[ \t]|$)",
        reply,
    ):
        return reply[line.start():].strip("\r\n")

    return reply

